UPDATE public.reviews SET content = replace(content, 'The review notes a missing leaf element, a minor manufacturing hiccup, but the overall impression is overwhelmingly positive.', 'The overall impression is overwhelmingly positive.') WHERE slug = 'lego-creative-flower-shop-42693-worth-2999' AND position('The review notes a missing leaf element, a minor manufacturing hiccup, but the overall impression is overwhelmingly positive.' in content) > 0;
UPDATE public.reviews SET content = replace(content, 'However, the review notes a significant number of stickers in this scene,', 'However, there are a significant number of stickers in this scene,') WHERE slug = 'lego-playstation-72306-worth-17000' AND position('However, the review notes a significant number of stickers in this scene,' in content) > 0;
