UPDATE public.reviews SET content = replace(content, 'The build experience, according to the review, is intricate,', 'The build is intricate,') WHERE slug = 'lego-sagrada-famlia-21065-worth-76400' AND position('The build experience, according to the review, is intricate,' in content) > 0;
